import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
import { get_asset_categories } from "@/mixins/GetAssetCategoryList.js";
import { get_asset_sub_categories } from "@/mixins/GetAssetSubCategories.js";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_verified_unverified_assets, asset_management_reports } from "@/graphql/queries.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import SnackBar from "@/components/SnackBar.vue";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  components: {
    SnackBar
  },
  mixins: [get_all_org_users, get_asset_categories, get_asset_sub_categories],
  data() {
    return {
      verificationAssets: [],
      pagination: {
        pageStart: 1,
        page: 1,
        rowsPerPage: 20,
        itemsPerPage: 20
      },
      categoriesName: "ALL",
      clearData: false,
      exportload: false,
      modal: false,
      asset_counts: {},
      date: new Date().toISOString().substr(0, 10),
      SnackBarComponent: {},
      verifiyTab: 0,
      goLoading: false,
      searchF: "",
      userselect: "ALL",
      nextToken: null,
      search: "",
      verificationFrequency: "",
      tableLoading: false,
      tableData: [],
      subcategory: "ALL",
      userArray: [],
      assetSubCategoriesList: [],
      allSubCategories: [],
      categoriesitems: [],
      headers: [{
        title: "Asset ID",
        value: "asset_prefix",
        sortable: false
      }, {
        title: "Asset QR ID",
        value: "asset_qr_label",
        sortable: false
      }, {
        title: "Category",
        value: "category_id_text",
        sortable: false
      }, {
        title: "Sub Category",
        value: "sub_category_id_text",
        sortable: false
      }, {
        title: "Location",
        value: "asset_location",
        sortable: false
      }, {
        title: "Assigned To",
        value: "asset_assined_to_name",
        sortable: false
      }, {
        title: "Verified On",
        value: "asset_verified_on",
        sortable: false
      }],
      currentPage: 1,
      itemsPerPage: 20,
      windowHeight: 0
    };
  },
  watch: {
    searchValue() {
      this.currentPage = 1;
    },
    verifiyTab() {
      this.userselect = "ALL";
      this.categoriesName = "ALL";
      this.assetSubCategoriesList = [];
      this.assetSubCategoriesList.push({
        text: "All",
        value: "ALL"
      });
      this.subcategory = "ALL";
      this.tableData = [];
      this.nextToken = null;
      this.fetch_list();
    }
  },
  async mounted() {
    this.$store.commit("Setnamesearch", "");
    var data = this.$store.getters.GetOrgDetails;
    this.verificationFrequency = data.organization.asset_verification_frequency != undefined ? data.organization.asset_verification_frequency : 3;
    this.date = this.subtractMonths(this.date, this.verificationFrequency);
    await Promise.all([this.get_all_org_users(), this.get_asset_categories(), this.get_asset_sub_categories(), this.fetch_list()]);
    await this.fetch_details();
    this.categoriesitems = this.assetCategories;
    this.categoriesitems.push({
      text: "All",
      value: "ALL"
    });
    this.allSubCategories = this.assetSubCategories;
    this.assetSubCategoriesList.push({
      text: "All",
      value: "ALL"
    });

    // Set up window height handling
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    filteredAssets() {
      const query = this.searchValue.toLowerCase().trim();
      if (!query) return this.tableData;
      return this.tableData.filter(asset => [asset.asset_prefix, asset.asset_qr_label, asset.category_id_text, asset.sub_category_id_text, asset.asset_location, asset.asset_assined_to_name].filter(Boolean).some(val => String(val).toLowerCase().includes(query)));
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredAssets.slice(start, end);
    },
    filteredAssets() {
      const query = this.searchValue?.toLowerCase().trim();
      if (!query) return this.tableData;
      return this.tableData.filter(asset => [asset.asset_prefix, asset.asset_qr_label, asset.category_id_text, asset.sub_category_id_text, asset.asset_location, asset.asset_assined_to_name].filter(Boolean).some(val => String(val).toLowerCase().includes(query)));
    },
    computedDateFormatted() {
      return this.formatDate(this.date);
    },
    totalCount() {
      return this.filteredAssets.length;
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    windowHeight() {
      return window.innerHeight - 360; // Adjust height based on header, tabs, and padding
    }
  },
  methods: {
    handlePagination_check1() {
      if (this.nextToken) {
        this.fetch_list();
      }
    },
    fetch_sub_data() {
      this.subcategory = "";
      var filteredArray = this.assetSubCategories.filter(obj => obj.category_id === this.categoriesName);
      this.assetSubCategoriesList = [];
      filteredArray.forEach(element => {
        this.assetSubCategoriesList.push({
          text: element.sub_category_name,
          value: element.sub_category_id
        });
      });
      //   console.log(this.assetSubCategoriesList);
    },
    fetch_details() {
      this.userArray = [{
        title: "ALL",
        user_id: "ALL"
      }];
      this.orgUsers.forEach(element => {
        if (element.user_status === "ACTIVE") {
          this.userArray.push({
            title: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    async get_data() {
      this.tableData = [];
      this.nextToken = null;
      this.fetch_list();
    },
    async clear_data() {
      this.userselect = "ALL";
      this.categoriesName = "ALL";
      this.assetSubCategoriesList = [];
      this.assetSubCategoriesList.push({
        text: "All",
        value: "ALL"
      });
      this.subcategory = "ALL";
      this.clearData = true;
      this.tableData = [];
      this.nextToken = null;
      this.fetch_list();
    },
    subtractMonths(dateString, monthsToSubtract) {
      // Parse the input date string
      const date = new Date(dateString);

      // Subtract the specified number of months
      date.setMonth(date.getMonth() - monthsToSubtract);

      // Format the date back to yyyy-MM-DD
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, "0"); // Months are zero-indexed
      const day = String(date.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    check_from_date(date) {
      this.$refs.dialog1.save(date);
      this.fetch_list();
    },
    formate_date(value) {
      var data = formatdisplayDate(value);
      return data;
    },
    async get_export() {
      this.exportload = true;
      try {
        let result = await API.graphql(graphqlOperation(asset_management_reports, {
          input: {
            asset_verirfication_status: this.verifiyTab == 0 ? "VERIFIED" : "UNVERIFIED",
            date: this.date,
            asset_assined_to: this.userselect,
            category_id: this.categoriesName,
            sub_category_id: this.subcategory
          }
        }));
        var response = JSON.parse(result.data.asset_management_reports);
        this.exportload = false;
        if (response.Status == "SUCCESS") {
          this.download_invoice(response.data);
          this.exportload = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.exportload = false;
        }
      } catch (error) {
        this.exportload = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_list() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(get_verified_unverified_assets, {
          input: {
            asset_verirfication_status: this.verifiyTab == 0 ? "VERIFIED" : "UNVERIFIED",
            date: this.date,
            asset_assined_to: this.userselect,
            category_id: this.categoriesName,
            sub_category_id: this.subcategory,
            nextToken: this.nextToken,
            limit: 50
          }
        }));
        var response = JSON.parse(result.data.get_verified_unverified_assets);
        this.tableLoading = false;
        this.clearData = false;
        if (response.Status == "SUCCESS") {
          this.nextToken = response.nextToken;
          var array = this.tableData.concat(response.data);
          const uniqueArrayOfObjects = array.filter((obj, index, self) => index === self.findIndex(o => o.asset_id === obj.asset_id));
          this.tableData = uniqueArrayOfObjects;
          this.tableLoading = false;
          this.clearData = false;
          this.asset_counts = {};
          this.asset_counts = response.asset_counts;
        } else {
          this.asset_counts = response.asset_counts;
          this.tableData = [];
          this.clearData = false;
          this.tableLoading = false;
        }
      } catch (error) {
        this.asset_counts = {
          verified_assets: 0,
          unverified_assets: 0,
          total_assets: 0
        };
        this.clearData = false;
        this.tableData = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async download_invoice(url) {
      var fileName = this.verifiyTab == 0 ? `Verified in the last ${this.verificationFrequency} month.xlsx` : `Not verified in the last ${this.verificationFrequency} month.xlsx`;
      axios({
        url: url,
        method: "GET",
        responseType: "blob" // Set the response type to blob
      }).then(response => {
        const blob = new Blob([response.data], {
          type: response.headers["content-type"]
        });

        // Use the FileSaver library to save the file
        FileSaver.saveAs(blob, fileName);
      }).catch(error => {
        console.error("Error downloading the file:", error);
      });
    },
    getcal() {
      this.modal = true;
    },
    formatDate(date) {
      if (!date) return null;
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    get_details() {},
    updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedItems = this.filteredAssets.slice(start, end);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 350; // Adjust height based on header, tabs, and padding
    }
  }
};
